#include <string>

#include "Halide.h"

// include common definitions (defines DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions
#include "mvt.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/**
 * Array initialization translated to Halide.
 *
 * Original C:
 *   for (i = 0; i < n; i++) {
 *     x1[i]  = (DATA_TYPE) (i % n) / n;
 *     x2[i]  = (DATA_TYPE) ((i + 1) % n) / n;
 *     y_1[i] = (DATA_TYPE) ((i + 3) % n) / n;
 *     y_2[i] = (DATA_TYPE) ((i + 4) % n) / n;
 *     for (j = 0; j < n; j++)
 *       A[i][j] = (DATA_TYPE) (i*j % n) / n;
 *   }
 *
 * Halide layout: A(j, i) corresponds to C A[i][j]
 */
static
void init_array(int n,
                Halide::Buffer<num_t, 1> x1,
                Halide::Buffer<num_t, 1> x2,
                Halide::Buffer<num_t, 1> y_1,
                Halide::Buffer<num_t, 1> y_2,
                Halide::Buffer<num_t, 2> A) {
    Var i("i"), j("j");

    Func init_x1("init_x1");
    Func init_x2("init_x2");
    Func init_y1("init_y1");
    Func init_y2("init_y2");
    Func init_A("init_A");

    // 1D vectors
    init_x1(i) = cast<num_t>(i % n) / cast<int>(n);
    init_x2(i) = cast<num_t>((i + 1) % n) / cast<int>(n);
    init_y1(i) = cast<num_t>((i + 3) % n) / cast<int>(n);
    init_y2(i) = cast<num_t>((i + 4) % n) / cast<int>(n);

    // 2D matrix A: C layout A[i][j] -> Halide A(j, i)
    init_A(j, i) = cast<num_t>((i * j) % n) / cast<int>(n);

    // Simple, cache-friendly schedule for initialization.
    // A is O(n^2) and dominates init cost, so we parallelize it.
    const int vec_width = 8; // reasonable default for modern x86
    init_A
        .compute_root()
        .parallel(i)          // rows (C's i) in parallel
        .vectorize(j, vec_width); // walk across C's j dimension contiguously

    // 1D vectors are cheap relative to A; just vectorize them.
    init_x1.compute_root().vectorize(i, vec_width);
    init_x2.compute_root().vectorize(i, vec_width);
    init_y1.compute_root().vectorize(i, vec_width);
    init_y2.compute_root().vectorize(i, vec_width);

    // Realize into the provided buffers
    init_x1.realize(x1);
    init_x2.realize(x2);
    init_y1.realize(y_1);
    init_y2.realize(y_2);
    init_A.realize(A);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;

    // Buffers corresponding to:
    //   DATA_TYPE A[N][N];
    //   DATA_TYPE x1[N], x2[N], y_1[N], y_2[N];
    //
    // PolyBench uses A[i][j]; we map j -> dim 0 (x), i -> dim 1 (y).
    Halide::Buffer<num_t, 2> A(n, n);     // (j, i)
    Halide::Buffer<num_t, 1> x1(n);
    Halide::Buffer<num_t, 1> x2(n);
    Halide::Buffer<num_t, 1> y_1(n);
    Halide::Buffer<num_t, 1> y_2(n);

    // ImageParams to feed into the Halide pipeline
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x1_param(type_of<num_t>(), 1, "x1_param");
    ImageParam x2_param(type_of<num_t>(), 1, "x2_param");
    ImageParam y1_param(type_of<num_t>(), 1, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 1, "y2_param");

    // Initialize data using a Halide-based initializer
    init_array(n, x1, x2, y_1, y_2, A);

    // Bind buffers to ImageParams
    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    // Halide translation of kernel_mvt:
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Mathematically:
    //   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //
    // With our (j, i) mapping for A[i][j]:
    //   A[i][j]  -> A_param(j, i)
    //   A[j][i]  -> A_param(i, j)

    Var i("i");
    // Use the width of A (dim 0, corresponding to j) as the reduction extent.
    RDom r(0, A.dim(0).extent(), "r");

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First loop nest: accumulate into x1
    //
    // x1(i) = x1(i) + sum_r A(i, r) * y1(r)
    // In Halide layout: A[i][j] -> A_param(j, i), so A(i, r) -> A_param(r, i).
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(r, i) * y1_param(r);

    // Second loop nest: accumulate into x2
    //
    // x2(i) = x2(i) + sum_r A(r, i) * y2(r)
    // In Halide layout: A[j][i] -> A_param(i, j), so A(r, i) -> A_param(i, r).
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // ------------------------------
    // Scheduling for performance
    // ------------------------------
    //
    // We have two independent matrix-vector-like reductions, each O(n^2).
    // The main performance goals are:
    //   - parallelize across 'i' (rows of the conceptual matrix),
    //   - vectorize across a contiguous dimension,
    //   - keep data access patterns cache-friendly.
    //
    // A is laid out as A(j, i) with j (dim 0) contiguous in memory.
    //  - For mvt_x2, we read A_param(i, r): for fixed r, i is the
    //    contiguous dimension (dim 0), so vectorizing across i gives
    //    unit-stride loads from A.
    //  - For mvt_x1, we read A_param(r, i): for fixed r, varying i
    //    walks along dim 1 (non-contiguous) and thus is strided.
    //    This is inherent to the algorithm (it multiplies both A and A^T),
    //    so at least one of the two passes must use non-contiguous
    //    accesses to A.
    //
    // We choose to:
    //   - tile 'i' into [io, ii], where 'ii' is vectorized and 'io' is
    //     parallelized,
    //   - in the reduction update, use loop order: for io (parallel),
    //     for r (reduction), for ii (vectorized).
    //
    // This gives:
    //   - good parallelism across rows (io),
    //   - vectorization across contiguous i for the A_param(i, r) access
    //     in mvt_x2,
    //   - reasonable cache behavior for both reductions.

    const int vec_width = 8;   // fixed SIMD width; Halide will legalize as needed
    const int i_tile    = 64;  // tile size along 'i' for parallel work chunks

    Var io("io"), ii("ii");

    // Schedule for mvt_x1
    mvt_x1
        .compute_root()
        // Tile i into outer (io) and inner (ii) pieces. The inner piece
        // will be vectorized, the outer run in parallel.
        .split(i, io, ii, i_tile)
        .parallel(io)
        .vectorize(ii, vec_width);

    mvt_x1.update()
        // Apply the same tiling to the update stage.
        .split(i, io, ii, i_tile)
        // Reorder so that the inner loop is 'ii' (vectorized), then the
        // reduction variable 'r', then the outer tile index 'io'.
        // Loop nest:
        //   for io (parallel tiles)
        //     for r (reduction over j)
        //       for ii (vectorized over i within tile)
        .reorder(ii, r, io)
        .parallel(io)
        .vectorize(ii, vec_width);

    // Schedule for mvt_x2 (mirrors mvt_x1)
    mvt_x2
        .compute_root()
        .split(i, io, ii, i_tile)
        .parallel(io)
        .vectorize(ii, vec_width);

    mvt_x2.update()
        .split(i, io, ii, i_tile)
        .reorder(ii, r, io)
        .parallel(io)
        .vectorize(ii, vec_width);

    // JIT-compile the two Funcs with the applied schedules
    mvt_x1.compile_jit();
    mvt_x2.compile_jit();

    // Time the kernel execution (both x1 and x2 updates)
    auto start = std::chrono::high_resolution_clock::now();

    // Realize back into x1 and x2 buffers (in-place relative to the C view)
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results to stderr (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print x1
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x1(idx) << '\n';
        }
        // Print x2
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x2(idx) << '\n';
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
