    // mvt_x1(i) = x1[i] + sum_r A[i][r] * y_1[r]
    // where A[i][r] -> A_param(r, i)
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(r, i) * y1_param(r);

    // Second loop nest: accumulate into x2
    //
    // mvt_x2(i) = x2[i] + sum_r A[r][i] * y_2[r]
    // where A[r][i] -> A_param(i, r)
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // ------------------------------------------------------------------
    // Scheduling for the MVT kernel
    // ------------------------------------------------------------------
    // We have a reduction over r and a pure index i. Updates for
    // different values of i are independent, so we can safely
    // parallelize and vectorize across i. The reduction is over r
    // (inner loop), matching the original C's j-inner, i-outer order
    // and giving good spatial locality on A(j, i).
    //
    // mvt_x1:
    mvt_x1.compute_root();
    // Parallelize different rows i across CPU cores.
    mvt_x1.parallel(i);
    // Vectorize across i (even though accesses to A are strided in i,
    // this still vectorizes operations on x1 and the scalar arithmetic).
    mvt_x1.vectorize(i, vec_width);
    // Apply the same schedule to the reduction update step.
    mvt_x1.update()
          .parallel(i)
          .vectorize(i, vec_width);

    // mvt_x2:
    mvt_x2.compute_root();
    mvt_x2.parallel(i);
    mvt_x2.vectorize(i, vec_width);
    mvt_x2.update()
          .parallel(i)
          .vectorize(i, vec_width);

    // JIT-compile the two Funcs once, for the current host target.
    mvt_x1.compile_jit(target);
    mvt_x2.compile_jit(target);

    // Time the kernel execution (both x1 and x2 updates)
    auto start = std::chrono::high_resolution_clock::now();

    // Realize back into x1 and x2 buffers (in-place relative to the C view)
    mvt_x1.realize(x1);
    mvt_x2.realize(x2);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optional: print results to stderr (similar spirit to PolyBench print_array)
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);

        // Print x1
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x1(idx) << '\n';
        }
        // Print x2
        for (int idx = 0; idx < n; idx++) {
            std::cerr << x2(idx) << '\n';
        }
    }

    // Print timing (seconds) to stdout
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
