    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    ImageParam x1_param(type_of<num_t>(), 1, "x1_param");
    ImageParam x2_param(type_of<num_t>(), 1, "x2_param");
    ImageParam y1_param(type_of<num_t>(), 1, "y1_param");
    ImageParam y2_param(type_of<num_t>(), 1, "y2_param");

    // Initialize data using a Halide-based initializer
    init_array(n, x1, x2, y_1, y_2, A);

    // Bind buffers to ImageParams
    A_param.set(A);
    x1_param.set(x1);
    x2_param.set(x2);
    y1_param.set(y_1);
    y2_param.set(y_2);

    // Halide translation of kernel_mvt:
    //
    // Original C kernel:
    //
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x1[i] = x1[i] + A[i][j] * y_1[j];
    // for (i = 0; i < N; i++)
    //   for (j = 0; j < N; j++)
    //     x2[i] = x2[i] + A[j][i] * y_2[j];
    //
    // Mathematically:
    //   x1[i] = x1[i] + sum_j A[i][j] * y_1[j]
    //   x2[i] = x2[i] + sum_j A[j][i] * y_2[j]
    //
    // With our (j, i) mapping for A[i][j]:
    //   A[i][j]  -> A_param(j, i)
    //   A[j][i]  -> A_param(i, j)

    Var i("i");
    // Use the width of A (dim 0, corresponding to j) as the reduction extent.
    RDom r(0, A.dim(0).extent(), "r");

    Func mvt_x1("mvt_x1");
    Func mvt_x2("mvt_x2");

    // First loop nest: accumulate into x1
    mvt_x1(i) = x1_param(i);
    mvt_x1(i) += A_param(r, i) * y1_param(r);

    // Second loop nest: accumulate into x2
    mvt_x2(i) = x2_param(i);
    mvt_x2(i) += A_param(i, r) * y2_param(r);

    // ------------------------------------------------------------------
    // Scheduling for the main MVT kernel
    //
    // Each i is independent: we have one reduction over r per i.
    // We exploit:
    //   - parallelism over i (outer tiles)
    //   - vectorization across the inner i tile
    //   - keep the reduction r innermost for streaming access to A.
    // ------------------------------------------------------------------
    Target target = get_host_target();
    const int vec = target.natural_vector_size<num_t>();
    const int tile_i = 256;  // tile size over i; chosen to amortize overhead

    Var io1("io1"), ii1("ii1");
    Var io2("io2"), ii2("ii2");

    // x1 pipeline
    mvt_x1
        .compute_root()
        .split(i, io1, ii1, tile_i)
        .parallel(io1)          // distribute tiles across cores
        .vectorize(ii1, vec);   // vectorize across contiguous i's

