        .split(i, io1, ii1, tile_i)
        // Loop order from outermost to innermost will be: io1, r, ii1.
        // ii1 is innermost and vectorized; r is kept in the middle to
        // stream across each row of A for a vector of i's.
        .reorder(ii1, r, io1)
        .parallel(io1)
        .vectorize(ii1, vec);

